-- xstate core schema: users, organizations, members, domains, mailboxes.
-- Stalwart (mx.xstate.com) is the source of truth for mail; these rows mirror it and add ownership and access.
-- Timestamps are ISO 8601 UTC strings. IDs are UUIDs generated by the API.

-- People who sign in to xstate.
CREATE TABLE users (
  id             TEXT PRIMARY KEY,
  email          TEXT NOT NULL UNIQUE,         -- sign-in email, lowercase
  name           TEXT,
  password_hash  TEXT,                         -- NULL for Google-only users
  google_sub     TEXT UNIQUE,                  -- Google account id, if linked
  created_at     TEXT NOT NULL,
  updated_at     TEXT NOT NULL
);

-- A workspace. One user owns it; that user also has a members row with role 'owner'.
CREATE TABLE organizations (
  id          TEXT PRIMARY KEY,
  name        TEXT NOT NULL,
  owner_id    TEXT NOT NULL REFERENCES users (id) ON DELETE RESTRICT,
  created_at  TEXT NOT NULL,
  updated_at  TEXT NOT NULL
);
CREATE INDEX organizations_owner_idx ON organizations (owner_id);

-- People in an organization and what they can do.
-- permissions (JSONB): {"org": ["domains.create", ...], "domains": {"*": "read", "<domain id>": "manage"}}
-- Owners and admins can do everything; permissions only apply to role 'member'.
CREATE TABLE members (
  id               TEXT PRIMARY KEY,
  organization_id  TEXT NOT NULL REFERENCES organizations (id) ON DELETE CASCADE,
  user_id          TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  role             TEXT NOT NULL DEFAULT 'member' CHECK (role IN ('owner', 'admin', 'member')),
  permissions      BLOB NOT NULL DEFAULT (jsonb('{"org":[],"domains":{}}')) CHECK (json_valid(permissions, 8)),
  created_at       TEXT NOT NULL,
  updated_at       TEXT NOT NULL,
  UNIQUE (organization_id, user_id)
);
CREATE INDEX members_user_idx ON members (user_id);

-- A customer domain in Stalwart (x:Domain).
CREATE TABLE domains (
  id               TEXT PRIMARY KEY,
  organization_id  TEXT NOT NULL REFERENCES organizations (id) ON DELETE RESTRICT,
  name             TEXT NOT NULL UNIQUE,       -- 'customer.com', lowercase
  stalwart_id      TEXT NOT NULL UNIQUE,
  status           TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'verified')),
  enabled          INTEGER NOT NULL DEFAULT 1,
  verified_at      TEXT,
  created_by       TEXT REFERENCES users (id) ON DELETE SET NULL,
  created_at       TEXT NOT NULL,
  updated_at       TEXT NOT NULL,
  UNIQUE (id, organization_id)                 -- target for composite FKs below
);
CREATE INDEX domains_org_idx ON domains (organization_id);

-- A mail store in Stalwart (x:Account). personal and agent mailboxes are @type User with their own
-- password; shared mailboxes are @type Group, opened by members through their personal mailbox.
CREATE TABLE mailboxes (
  id               TEXT PRIMARY KEY,
  organization_id  TEXT NOT NULL REFERENCES organizations (id) ON DELETE RESTRICT,
  kind             TEXT NOT NULL DEFAULT 'personal' CHECK (kind IN ('personal', 'shared', 'agent')),
  display_name     TEXT,
  quota_bytes      INTEGER,                    -- NULL = no limit
  stalwart_id      TEXT NOT NULL UNIQUE,
  created_by       TEXT REFERENCES users (id) ON DELETE SET NULL,
  created_at       TEXT NOT NULL,
  updated_at       TEXT NOT NULL,
  UNIQUE (id, organization_id)
);
CREATE INDEX mailboxes_org_idx ON mailboxes (organization_id);

-- Every address that delivers somewhere: one primary per mailbox, plus aliases on any domain of the org.
CREATE TABLE addresses (
  id               TEXT PRIMARY KEY,
  organization_id  TEXT NOT NULL,
  mailbox_id       TEXT NOT NULL,
  domain_id        TEXT NOT NULL,
  local_part       TEXT NOT NULL,              -- 'support', lowercase
  address          TEXT NOT NULL UNIQUE,       -- 'support@customer.com'
  is_primary       INTEGER NOT NULL DEFAULT 0,
  created_at       TEXT NOT NULL,
  FOREIGN KEY (mailbox_id, organization_id) REFERENCES mailboxes (id, organization_id) ON DELETE CASCADE,
  FOREIGN KEY (domain_id, organization_id) REFERENCES domains (id, organization_id) ON DELETE RESTRICT
);
CREATE UNIQUE INDEX addresses_one_primary ON addresses (mailbox_id) WHERE is_primary = 1;
CREATE INDEX addresses_mailbox_idx ON addresses (mailbox_id);
CREATE INDEX addresses_domain_idx ON addresses (domain_id);

-- Which members can open which mailboxes. 'owner' is the person a personal mailbox belongs to.
CREATE TABLE mailbox_access (
  mailbox_id  TEXT NOT NULL REFERENCES mailboxes (id) ON DELETE CASCADE,
  member_id   TEXT NOT NULL REFERENCES members (id) ON DELETE CASCADE,
  access      TEXT NOT NULL DEFAULT 'full' CHECK (access IN ('owner', 'full', 'read')),
  created_at  TEXT NOT NULL,
  PRIMARY KEY (mailbox_id, member_id)
);
CREATE INDEX mailbox_access_member_idx ON mailbox_access (member_id);
